namespace Kassyi.GSharp.Compiler;

/// <summary>Generates host-side C# wrapper classes that JIT-compile and invoke GPU kernels.</summary>
/// <remarks><para>Implements: <b>GEN-35</b></para></remarks>
internal static class WrapperEmitter
{
    public static string GenerateWrapperClass(IMethodSymbol method, string source, GeneratorConfig config,
        byte[]? aesKey = null, string? keyProvider = null)
    {
        var className = method.ContainingType.Name + "Wrapper";

        var writer = new SourceWriter();
        writer.AppendLine("""
            // <auto-generated/>
            #nullable enable
            using System;
            #pragma warning disable RS1035 // Do not use APIs banned for analyzers
            #pragma warning disable RS1016
            #pragma warning disable RS1034
            using System.Text;
            using System.Runtime.InteropServices;
            using global::Kassyi.GSharp.Core;
            using global::Kassyi.GSharp.Runtime.Interop;
            """);

        writer.AppendLine();
        writer.Append("namespace ");
        if (method.ContainingNamespace.IsGlobalNamespace)
        {
            writer.AppendLine("Kassyi.GSharp.Generated");
        }
        else
        {
            WriteNamespace(writer, method.ContainingNamespace);
            writer.AppendLine();
        }

        using (writer.Scope())
        {
            writer.Append("public static partial class ");
            writer.AppendLine(className);
            using (writer.Scope())
            {
                WriteKernelSource(writer, method, source, config);
                MarshalingEmitter.WriteStructMarshaling(writer, method);

                writer.AppendLine($"private static byte[]? s_decryptionKey_{method.Name};");
                writer.AppendLine($"private static byte[]? s_binaryData_{method.Name};");
                writer.AppendLine($"private static bool s_isLoaded_{method.Name};");

                if (aesKey != null)
                {
                    if (string.IsNullOrWhiteSpace(keyProvider))
                    {
                        VmObfuscatorEmitter.EmitKeyDerivationVm(writer, method, aesKey);
                    }
                }

                if (config.TargetDialect.Equals("Cuda", StringComparison.OrdinalIgnoreCase))
                {
                    WriteLaunchMethod(writer, method, false, aesKey != null, keyProvider);
                    WriteLaunchMethod(writer, method, true, aesKey != null, keyProvider);
                }
                else
                {
                    WriteLaunchMethodCpu(writer, method, aesKey != null, keyProvider);
                }
            }
        }

        return writer.ToString();
    }

    private static void WriteKernelSource(SourceWriter writer, IMethodSymbol method, string source,
        GeneratorConfig config)
    {
        if (config.EmitSource)
        {
            var escapedSource = source.Replace("\"", "\"\"");
            writer.AppendLine($"public const string {method.Name}_Source = @\"{escapedSource}\";");
            writer.AppendLine(
                $"public static readonly string {method.Name}_FullSource = global::Kassyi.GSharp.Generated.GSharpShared{config.TargetDialect}Prelude.Source + global::Kassyi.GSharp.Generated.GSharpShared{config.TargetDialect}DeviceCode.Source + {method.Name}_Source;");
            writer.AppendLine();
        }
    }

    private static void WriteLaunchMethod(SourceWriter writer, IMethodSymbol method, bool isDevicePtr,
        bool hasAesKey, string? keyProvider)
    {
        writer.AppendLine(
            "#pragma warning disable CS8500 // Takes the address of, gets the size of, or declares a pointer to a managed type");
        WriteLaunchMethodSignature(writer, method, isDevicePtr);
        using (writer.Scope())
        {
            if (!isDevicePtr)
            {
                WriteOutParameterDefaults(writer, method);
                WriteEmptyArrayGuards(writer, method);
            }

            WriteAutoResultAllocation(writer, method);

            writer.AppendLine(
                "using (var _cudaCtxScope = new global::Kassyi.GSharp.Runtime.Aot.GpuKernelLoader.CudaContextScope())");
            using (writer.Scope())
            {
                WriteCudaKernelCompilationCall(writer, method, hasAesKey, keyProvider);
                MarshalingEmitter.WriteVariablesInitialization(writer, method, isDevicePtr);

                writer.AppendLine("try");
                using (writer.Scope())
                {
                    MarshalingEmitter.WriteMarshalAndLaunchKernel(writer, method, isDevicePtr);
                }

                writer.AppendLine("finally");
                using (writer.Scope())
                {
                    MarshalingEmitter.WriteCleanup(writer, method, isDevicePtr);
                }
            }

            WriteAutoResultReturn(writer, method);
        }

        writer.AppendLine("#pragma warning restore CS8500");
    }

    private static void WriteLaunchMethodCpu(SourceWriter writer, IMethodSymbol method,
        bool hasAesKey, string? keyProvider)
    {
        writer.AppendLine("#pragma warning disable CS8500");
        WriteCpuDelegateDeclaration(writer, method);
        WriteLaunchMethodSignature(writer, method, false);
        using (writer.Scope())
        {
            WriteOutParameterDefaults(writer, method);
            WriteEmptyArrayGuards(writer, method);
            WriteCpuDelegateGetOrCompile(writer, method, hasAesKey, keyProvider);
            WriteCpuFixedBlocksAndInvoke(writer, method);
        }

        writer.AppendLine("#pragma warning restore CS8500");
    }

    private static void WriteLaunchMethodSignature(SourceWriter writer, IMethodSymbol method, bool isDevicePtr)
    {
        writer.Append("public static unsafe ");
        if (method.ReturnType.SpecialType != SpecialType.System_Void)
        {
            writer.AppendFullyQualifiedCsharpName(method.ReturnType);
            writer.Append("[] ");
        }
        else
        {
            writer.Append("void ");
        }

        writer.Append("Launch_");
        writer.Append(method.Name);
        if (isDevicePtr)
        {
            writer.Append("_Device");
        }

        using (writer.Parentheses())
        {
            var first = true;
            foreach (var p in method.Parameters)
            {
                if (!first)
                {
                    writer.AppendComma();
                    writer.AppendSpace();
                }

                if (isDevicePtr && (p.Type is IArrayTypeSymbol || p.RefKind is RefKind.Ref or RefKind.Out))
                {
                    writer.Append("IntPtr ");
                }
                else
                {
                    if (p.RefKind == RefKind.Ref)
                    {
                        writer.Append("ref ");
                    }
                    else if (p.RefKind == RefKind.Out)
                    {
                        writer.Append("out ");
                    }

                    writer.AppendFullyQualifiedCsharpName(p.Type);
                    writer.AppendSpace();
                }

                writer.Append(p.Name);

                first = false;
            }

            if (!first)
            {
                writer.AppendComma();
                writer.AppendSpace();
            }

            writer.Append(
                "uint gridDimX = 1, uint gridDimY = 1, uint gridDimZ = 1, uint blockDimX = 1, uint blockDimY = 1, uint blockDimZ = 1, uint sharedMemBytes = 0, System.ReadOnlySpan<System.Collections.Generic.KeyValuePair<string, string>> macros = default");
        }

        writer.AppendLine();
    }

    private static void WriteOutParameterDefaults(SourceWriter writer, IMethodSymbol method)
    {
        foreach (var p in method.Parameters)
        {
            if (p.RefKind is not RefKind.Out || p.Type is IArrayTypeSymbol)
            {
                continue;
            }

            writer.Append(p.Name);
            writer.AppendLine(" = default;");
        }
    }

    private static void WriteEmptyArrayGuards(SourceWriter writer, IMethodSymbol method)
    {
        var hasArray = false;
        foreach (var p in method.Parameters)
        {
            if (p.Type is not IArrayTypeSymbol)
            {
                continue;
            }

            hasArray = true;
            break;
        }

        if (!hasArray)
        {
            return;
        }

        writer.Append("if ");
        using (writer.Parentheses())
        {
            var isFirst = true;
            foreach (var p in method.Parameters)
            {
                if (p.Type is not IArrayTypeSymbol)
                {
                    continue;
                }

                if (!isFirst)
                {
                    writer.Append(" || ");
                }

                writer.Append(p.Name);
                writer.Append(".Length == 0");
                isFirst = false;
            }
        }

        using (writer.Scope())
        {
            if (method.ReturnType.SpecialType != SpecialType.System_Void)
            {
                writer.Append("return System.Array.Empty<");
                writer.AppendFullyQualifiedCsharpName(method.ReturnType);
                writer.AppendLine(">();");
            }
            else
            {
                writer.AppendLine("return;");
            }
        }

        writer.AppendLine();
    }


    private static void WriteCudaKernelCompilationCall(SourceWriter writer, IMethodSymbol method,
        bool hasAesKey, string? keyProvider)
    {
        writer.AppendLine($"if (!s_isLoaded_{method.Name})");
        using (writer.Scope())
        {
            writer.AppendLine(
                $"var fatbinPath = System.IO.Path.Combine(System.AppContext.BaseDirectory, \"{method.ContainingType.Name}_{method.Name}.fatbin\");");
            writer.AppendLine("if (System.IO.File.Exists(fatbinPath))");
            using (writer.Scope())
            {
                writer.AppendLine($"s_binaryData_{method.Name} = System.IO.File.ReadAllBytes(fatbinPath);");
                if (hasAesKey)
                {
                    if (!string.IsNullOrWhiteSpace(keyProvider))
                    {
                        writer.AppendLine(
                            $"s_decryptionKey_{method.Name} = {method.ContainingType.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat)}.{keyProvider}();");
                    }
                    else
                    {
                        writer.AppendLine($"s_decryptionKey_{method.Name} = DeriveObfuscatedKey_{method.Name}();");
                    }
                }
                else
                {
                    writer.AppendLine($"s_decryptionKey_{method.Name} = null;");
                }
            }
            writer.AppendLine("else");
            using (writer.Scope())
            {
                writer.AppendLine(
                    $"throw new System.InvalidOperationException($\"AOT kernel binary '{method.ContainingType.Name}_{method.Name}.fatbin' was not found at '{{fatbinPath}}'.\");");
            }
            writer.AppendLine($"s_isLoaded_{method.Name} = true;");
        }

        writer.AppendLine(
            $"IntPtr hfunc = global::Kassyi.GSharp.Runtime.Aot.GpuKernelLoader.LoadAotKernel(s_binaryData_{method.Name}, \"{method.Name}\", s_decryptionKey_{method.Name});");
        writer.AppendLine();
    }

    private static void WriteCpuDelegateDeclaration(SourceWriter writer, IMethodSymbol method)
    {
        // Generate Delegate
        writer.AppendLine(
            "[System.Runtime.InteropServices.UnmanagedFunctionPointer(System.Runtime.InteropServices.CallingConvention.Cdecl)]");
        writer.Append("private unsafe delegate void ");
        writer.Append(method.Name);
        writer.Append("_Delegate");
        using (writer.Parentheses())
        {
            writer.Append(
                "uint gridDimX, uint gridDimY, uint gridDimZ, uint blockDimX, uint blockDimY, uint blockDimZ");
            foreach (var p in method.Parameters)
            {
                if (p.HasAttribute(KnownAttributes.Constant))
                {
                    continue;
                }

                writer.AppendComma();
                writer.AppendSpace();

                if (p.Type is IArrayTypeSymbol arrayType)
                {
                    writer.AppendFullyQualifiedCsharpName(arrayType.ElementType);
                    writer.Append("* ");
                    writer.Append(p.Name);
                }
                else
                {
                    writer.AppendFullyQualifiedCsharpName(p.Type);
                    if (p.RefKind is RefKind.Ref or RefKind.Out)
                    {
                        writer.Append("*");
                    }

                    writer.AppendSpace();
                    writer.Append(p.Name);
                }
            }

            if (method.ReturnType.SpecialType != SpecialType.System_Void)
            {
                writer.AppendComma();
                writer.AppendSpace();
                writer.AppendFullyQualifiedCsharpName(method.ReturnType);
                writer.Append("* __gsharp_auto_result");
            }
        }

        writer.AppendLine(";");
        writer.AppendLine();
    }

    private static void WriteCpuDelegateGetOrCompile(SourceWriter writer, IMethodSymbol method,
        bool hasAesKey, string? keyProvider)
    {
        writer.AppendLine(
            "var archSuffix = System.Runtime.InteropServices.RuntimeInformation.ProcessArchitecture == System.Runtime.InteropServices.Architecture.Arm64 ? \"_arm64\" : \"_x64\";");
        writer.AppendLine(
            $"var dllName = $\"{method.ContainingType.Name}_{method.Name}{{archSuffix}}.dll\";");
        writer.AppendLine(
            "var dllPath = System.IO.Path.Combine(System.AppContext.BaseDirectory, dllName);");

        writer.AppendLine($"if (!s_isLoaded_{method.Name})");
        using (writer.Scope())
        {
            if (hasAesKey)
            {
                if (!string.IsNullOrWhiteSpace(keyProvider))
                {
                    writer.AppendLine(
                        $"s_decryptionKey_{method.Name} = {method.ContainingType.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat)}.{keyProvider}();");
                }
                else
                {
                    writer.AppendLine($"s_decryptionKey_{method.Name} = DeriveObfuscatedKey_{method.Name}();");
                }
            }
            else
            {
                writer.AppendLine($"s_decryptionKey_{method.Name} = null;");
            }

            writer.AppendLine($"s_isLoaded_{method.Name} = true;");
        }

        writer.AppendLine(
            $"var hfunc = global::Kassyi.GSharp.Runtime.Aot.CpuKernelLoader.LoadAotKernel<{method.Name}_Delegate>(\"__gsharp_launch_{method.Name}\", dllPath, s_decryptionKey_{method.Name});");
    }

    private static void WriteCpuFixedBlocksAndInvoke(SourceWriter writer, IMethodSymbol method)
    {
        var hasFixed = method.ReturnType.SpecialType != SpecialType.System_Void;
        if (!hasFixed)
        {
            foreach (var p in method.Parameters)
            {
                if (p.Type is IArrayTypeSymbol ||
                    (p.RefKind is RefKind.Ref or RefKind.Out && p.Type is not IArrayTypeSymbol))
                {
                    hasFixed = true;
                    break;
                }
            }
        }

        if (hasFixed)
        {
            foreach (var p in method.Parameters)
            {
                if (p.Type is not IArrayTypeSymbol arrayType)
                {
                    continue;
                }

                writer.Append("fixed (");
                writer.AppendFullyQualifiedCsharpName(arrayType.ElementType);
                writer.AppendLine($"* p_{p.Name} = {p.Name})");
            }

            if (method.ReturnType.SpecialType != SpecialType.System_Void)
            {
                WriteAutoResultAllocation(writer, method);
                writer.Append("fixed (");
                writer.AppendFullyQualifiedCsharpName(method.ReturnType);
                writer.AppendLine("* p___gsharp_auto_result = __gsharp_auto_result)");
            }

            foreach (var p in method.Parameters)
            {
                if (p.RefKind is not (RefKind.Ref or RefKind.Out) || p.Type is IArrayTypeSymbol)
                {
                    continue;
                }

                writer.Append("fixed (");
                writer.AppendFullyQualifiedCsharpName(p.Type);
                writer.AppendLine($"* p_{p.Name} = &{p.Name})");
            }

            using (writer.Scope())
            {
                WriteDelegateInvocation(writer, method);
            }
        }
        else
        {
            WriteDelegateInvocation(writer, method);
        }

        WriteAutoResultReturn(writer, method);
    }

    private static void WriteDelegateInvocation(SourceWriter writer, IMethodSymbol method)
    {
        writer.Append("hfunc");
        using (writer.Parentheses())
        {
            writer.Append("gridDimX, gridDimY, gridDimZ, blockDimX, blockDimY, blockDimZ");

            foreach (var p in method.Parameters)
            {
                if (p.HasAttribute(KnownAttributes.Constant))
                {
                    continue;
                }

                writer.AppendComma();
                writer.AppendSpace();

                if (p.Type is IArrayTypeSymbol || p.RefKind is RefKind.Ref or RefKind.Out)
                {
                    writer.Append("p_");
                    writer.Append(p.Name);
                }
                else
                {
                    writer.Append(p.Name);
                }
            }

            if (method.ReturnType.SpecialType != SpecialType.System_Void)
            {
                writer.AppendComma();
                writer.AppendSpace();
                writer.Append("p___gsharp_auto_result");
            }
        }

        writer.AppendLine(";");
    }

    private static void WriteAutoResultAllocation(SourceWriter writer, IMethodSymbol method)
    {
        if (method.ReturnType.SpecialType != SpecialType.System_Void)
        {
            writer.AppendLine(
                "uint __gsharp_total_threads = (gridDimX * gridDimY * gridDimZ) * (blockDimX * blockDimY * blockDimZ);");
            writer.Append("var __gsharp_auto_result = new ");
            writer.AppendFullyQualifiedCsharpName(method.ReturnType);
            writer.AppendLine("[__gsharp_total_threads];");
        }
    }

    private static void WriteAutoResultReturn(SourceWriter writer, IMethodSymbol method)
    {
        if (method.ReturnType.SpecialType != SpecialType.System_Void)
        {
            writer.AppendLine("return __gsharp_auto_result;");
        }
    }

    private static void WriteNamespace(SourceWriter writer, INamespaceSymbol ns)
    {
        if (ns.ContainingNamespace is not null && !ns.ContainingNamespace.IsGlobalNamespace)
        {
            WriteNamespace(writer, ns.ContainingNamespace);
            writer.Append('.');
        }

        writer.Append(ns.Name);
    }
}
